SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='55713523-14fd-5f4c-8762-80f92d11aa5f'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('cea9e90d-610d-5540-9010-3d08486c2c24','4e8f6d69-0a70-5c5e-85df-c3a306c09187')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='55713523-14fd-5f4c-8762-80f92d11aa5f'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='55713523-14fd-5f4c-8762-80f92d11aa5f'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('cea9e90d-610d-5540-9010-3d08486c2c24','4e8f6d69-0a70-5c5e-85df-c3a306c09187')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='55713523-14fd-5f4c-8762-80f92d11aa5f'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
