  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-customer-10-result-version' AND q.fingerprint='b0ff39974d909ed1f351265a9c40090ec29013382d17b79e20907ecadce9510c'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"customer-10-result-version","status":"ok","value":{"customerProfileId":"55713523-14fd-5f4c-8762-80f92d11aa5f","userId":"a66b0760-39ad-56a0-868a-20f99d08bd46","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"cea9e90d-610d-5540-9010-3d08486c2c24","semanticKey":"customer-controls-customer-10-result-version","fingerprint":"b0ff39974d909ed1f351265a9c40090ec29013382d17b79e20907ecadce9510c","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='c45c8bbf-827b-58c6-a4d6-7f66d4d47b1d' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='09b665aa-8aee-5d84-94d4-6eb14cab8dfd' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"55713523-14fd-5f4c-8762-80f92d11aa5f"},"prior":null,"committed":{"id":"55713523-14fd-5f4c-8762-80f92d11aa5f","userId":"a66b0760-39ad-56a0-868a-20f99d08bd46","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='55713523-14fd-5f4c-8762-80f92d11aa5f' AND c.user_id='a66b0760-39ad-56a0-868a-20f99d08bd46' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
