   AND o.aggregate_kind='CustomerProfile' AND o.aggregate_id=c.id::text AND o.source_revision=0 AND o.source_generation=0 AND o.schema_version='1'
   AND o.causation_id=q.id::text AND o.correlation_id='customer-10-result-version' AND o.mutation_transaction_id=c.mutation_transaction_id
   AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
   AND ((o.id='8ad3f9be-6049-50a6-90eb-cab8d54a3379' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"55713523-14fd-5f4c-8762-80f92d11aa5f","userId":"a66b0760-39ad-56a0-868a-20f99d08bd46","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='56f35c3c-0930-5515-9e58-12cd2bc9cd92' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"a66b0760-39ad-56a0-868a-20f99d08bd46","track":"customer","customerProfileId":"55713523-14fd-5f4c-8762-80f92d11aa5f","sourceCreationRevision":"0","sourceCreationReceipt":"cea9e90d-610d-5540-9010-3d08486c2c24","semanticKey":"customer_buyer_profile/55713523-14fd-5f4c-8762-80f92d11aa5f/default-free-enrollment/v1"}'::jsonb)))=2));
